(window.LART=window.LART||{})["复杂数据结构/RMQ问题"]="<p><a href=\"https://oi-wiki.net/topic/rmq/\">RMQ - OI Wiki (oi-wiki.net)</a></p>\n\n<p><code>Range Maximum/Minimum Query</code>，表示区间最大（最小）值，简称<code>RMQ</code>。</p>\n\n<p>在接下来的描述中，默认初始数组大小为 $n$，询问次数为 $m$。<br />\n在接下来的描述中，默认时间复杂度标记方式为$O(A)\\sim O(B)$，其中$O(A)$表示预处理时间复杂度，而$O(B)$表示单次询问的时间复杂度。</p>\n\n<h1>例题</h1>\n\n<p>洛谷题号：P3865</p>\n\n<p>给一个长度 $n$ 的数组 $a$。总共 $m$ 次查询，每次查询区间 $[l, r]$ 之间的最大值？<br />\n（$a_l,a_{l+1},a_{l+2},...,a_r$）</p>\n\n<h1>ST 表</h1>\n\n<p><a class=\"wiki-link\" href=\"#复杂数据结构/ST表\" data-rel=\"复杂数据结构/ST表\">ST表</a></p>\n\n<h1>线段树</h1>\n\n<p><a class=\"wiki-link\" href=\"#复杂数据结构/线段树/线段树\" data-rel=\"复杂数据结构/线段树/线段树\">线段树</a></p>\n\n<h1>单调栈+笛卡尔树+Tarjan求lca</h1>\n\n<p><a class=\"wiki-link\" href=\"#复杂数据结构/单调栈\" data-rel=\"复杂数据结构/单调栈\">单调栈</a><br />\n<a class=\"wiki-link\" href=\"#树论/笛卡尔树\" data-rel=\"树论/笛卡尔树\">笛卡尔树</a><br />\n<a class=\"wiki-link\" href=\"#树论/最近公共祖先\" data-rel=\"树论/最近公共祖先\">最近公共祖先</a></p>\n\n<h1>对比</h1>\n<div class=\"blanks\" style=\"height:1em\"></div>\n<table>\n<thead>\n<tr>\n<th>算法/数据结构</th>\n<th>预处理</th>\n<th>单次查询</th>\n<th>在线/离线</th>\n<th>支持修改</th>\n<th>要求掌握</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>ST</code> 表</td>\n<td>$O(n\\log n)$</td>\n<td>$O(1)$</td>\n<td>在线</td>\n<td>只能在末尾添加</td>\n<td>✔</td>\n</tr>\n<tr>\n<td>线段树</td>\n<td>$O(n)$</td>\n<td>$O(\\log n)$</td>\n<td>在线</td>\n<td>可以任意修改</td>\n<td>✔✔✔✔✔</td>\n</tr>\n<tr>\n<td>单调栈+笛卡尔树+<code>Tarjan</code>求<code>lca</code></td>\n<td>$O(n)$</td>\n<td>均摊$O(1)$</td>\n<td>离线</td>\n<td>❌</td>\n<td></td>\n</tr>\n</tbody>\n</table>\n";
